    import asyncio

    def _sync_update():
        supabase = get_supabase()
        clean_id = str(order_id).replace("P-", "").lstrip("0")
        try:
            int_id = int(clean_id)
            existing = supabase.table("ORDERS").select('"Tracking Number", "Whatsapp"').eq("Order ID", int_id).execute()
