                # Modificación: Permitir a los administradores acceder sin restricciones
                if caller_whatsapp and db_clean != caller_clean and not caller_whatsapp == "admin":
                    raise ValueError("Acceso Denegado: Solo el número que creó el pedido original puede modificarlo.")

